#!/usr/bin/env python3
"""Repro: XNNPACK delegated bug `hardtanh` (x86 host runtime, xnnpack_client).
hardtanh(NaN) returns the clamp bound on XNNPACK (fp16 SIMD fmin/fmax launders NaN) where ATen returns NaN.
Single-op graph from corpus job w108:307 (delegated to XNNPACK), non-finite leaf from injection.
Needs a connected xnnpack worker (BROKER_JOB_PORT, default 15564).
"""
import os,sys,time,warnings,logging
os.environ.setdefault("CUDA_VISIBLE_DEVICES",""); warnings.filterwarnings("ignore"); logging.disable(logging.WARNING)
sys.path.insert(0,"/data/jwen929")
import torch,zmq
from mobile.gen.export import build_job
from mobile.net import protocol as P, compare as cmp
JOB='w108:307'; PORT=int(os.environ.get("BROKER_JOB_PORT","15564")); SRC='# delegated: backend=xnnpack ops=1 non_delegated=0 delegate_calls=1\n"""Auto-generated by mobile — graph definition.\nGraph: n0*=hardtanh(L0,·,·)\nRun via the mobile ExecuTorch fuzzer (xnnpack_client / ...).\n"""\nimport torch\ntorch.manual_seed(12648430)  # reproducible leaf data\n\ndef _make(shape, dtype):\n    if dtype.is_floating_point or dtype.is_complex:\n        return torch.randn(shape, dtype=dtype)\n    if dtype == torch.bool:\n        return torch.randint(0, 2, shape, dtype=dtype)\n    lo = -4 if dtype.is_signed else 0  # unsigned dtypes reject a negative low\n    return torch.randint(lo, 5, shape, dtype=dtype)\n\n_NONFIN_P = 0.05  # single-op domain-fuzz probability\ndef _inject(t):\n    # exercise non-finite / boundary INPUT domains (NaN/inf/-inf/0/-0).\n    if not t.dtype.is_floating_point or t.numel() == 0:\n        return t  # nan/inf only meaningful for real floats\n    if torch.rand(1).item() >= _NONFIN_P:\n        return t  # leave this leaf clean\n    choices = [float(\'nan\'), float(\'inf\'), float(\'-inf\'), 0.0, -0.0]\n    v = choices[int(torch.randint(len(choices), (1,)).item())]\n    mask = torch.rand(t.shape) < 0.5\n    mask.reshape(-1)[0] = True  # guarantee >=1 injected element\n    return torch.where(mask, torch.full_like(t, v), t)\n\ndef _first(r):\n    if isinstance(r, torch.Tensor): return r\n    if isinstance(r, (tuple, list)):\n        for x in r:\n            if isinstance(x, torch.Tensor): return x\n    return r\n\nL0 = _inject(_make((3, 4, 3, 1, 2), torch.float16))\n\ndef g(L0):\n    n0 = _first(torch.ops.aten.hardtanh.default(L0, -8.0, -3))\n    return (n0,)\n\nLEAVES = [L0]'
job=build_job(SRC,"xnnpack",False)
if job.status!="READY": print(f"[{JOB}] build {job.status}: {job.detail[:160]}"); sys.exit(0)
ctx=zmq.Context.instance(); D=ctx.socket(zmq.DEALER); D.setsockopt(zmq.HEARTBEAT_IVL,5000); D.connect(f"tcp://127.0.0.1:{PORT}")
PL=zmq.Poller(); PL.register(D,zmq.POLLIN)
fr=P.encode_pushjob(f"repro::hardtanh",job.pte,job.inputs,job.eager,desc="repro",user_pos=job.user_pos,delegated={"ops":1})
D.send_multipart(P.job_frames_from_pushjob(fr)); t0=time.monotonic()
while time.monotonic()-t0<60:
    if dict(PL.poll(1000)).get(D):
        _,st,det,raw=P.decode_result(D.recv_multipart())
        if st!="RAN": print(f"[{JOB}] device status: {st} {det[:150]}"); break
        et=cmp.select(raw,job.user_pos)
        if len(et)>len(job.eager): et=et[len(et)-len(job.eager):]
        s,d=cmp._cmp(job.eager[0],et[0],0)
        print(f"[{JOB}] hardtanh -> {s} {d}"); print("  eager :",job.eager[0].flatten()[:8].tolist()); print("  device:",et[0].flatten()[:8].tolist()); break
